// fastly.error keeps EUTF8 after a later successful call:
// https://fiddle.fastly.dev/fiddle/d148fab2
func Test_Utf8_translate_error_persists(t *testing.T) {
	ctx := &context.Context{FastlyError: &value.String{IsNotSet: true}}
	call := func(input string) value.Value {
		ret, err := Utf8_translate(
			ctx,
			&value.String{Value: input},
			&value.String{Value: "a"},
			&value.String{Value: "x"},
		)
		if err != nil {
			t.Fatalf("Unexpected error: %s", err)
		}
		return ret
	}

	call("a\xffb")
	ret := value.Unwrap[*value.String](call("abc"))
	if diff := cmp.Diff("xbc", ret.Value); diff != "" {
		t.Errorf("Return value unmatch, diff=%s", diff)
	}
	if diff := cmp.Diff("EUTF8", ctx.FastlyError.Value); diff != "" {
		t.Errorf("fastly.error unmatch, diff=%s", diff)
	}
}
